const icons={heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h2m4 0h2m-8 3h2"/>',coffee:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8Zm13 1h2a3 3 0 1 1 0 6h-2M7 2v3m5-3v3M2 22h18"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m0-18a4 4 0 0 1 0 8m3 3a7 7 0 0 1 3 7"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3Zm8-1v4m-2-2h4"/>',check:'<path d="m5 12 4 4L19 6"/>',film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4m-4 8h4m10-8h4m-4 8h4"/>',food:'<path d="M4 2v7a3 3 0 0 0 6 0V2M7 2v20M20 22V2c-5 1-5 10 0 11"/>',compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',music:'<path d="M9 18V5l12-3v13M9 9l12-3"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="18" cy="15" rx="3" ry="3"/>',message:'<path d="M21 11.5a9 9 0 0 1-9.5 9A10 10 0 0 1 7 19.4L2 21l1.6-5a10 10 0 0 1-1.1-4.5A9 9 0 0 1 12 2a9 9 0 0 1 9 9.5Z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 6 6"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 7L22 6"/>',logout:'<path d="M9 21H4V3h5m5 4 5 5-5 5m-6-5h13"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-11v1"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const profiles=[{id:'ananya',name:'Ananya',age:38,gender:'woman',city:'Bengaluru',area:'Indiranagar',image:'sample-ananya.jpg',line:'A good coffee, a long walk, a great story.',bio:'A curious soul who loves discovering little cafés, getting lost in bookshops, and finding the extraordinary in everyday conversations.',interests:['Coffee & conversations','City exploring','Books & art'],languages:['English','Hindi','Kannada'],color:'rose'},{id:'arjun',name:'Arjun',age:29,gender:'man',city:'Mumbai',area:'Bandra West',image:'sample-arjun.jpg',line:'Your next adventure starts with a hello.',bio:'Weekend explorer, cinema enthusiast, and enthusiastic finder of Mumbai’s best street food. Always up for a relaxed conversation and a new perspective.',interests:['City exploring','Movies','Food & dining'],languages:['English','Hindi','Marathi'],color:'sage'},{id:'meera',name:'Meera',age:28,gender:'woman',city:'Delhi',area:'Hauz Khas',image:'sample-meera.jpg',line:'Let’s turn an ordinary day into a good one.',bio:'Art galleries, live music, and meaningful conversations are my kind of plans. I love meeting people who see the world a little differently.',interests:['Coffee & conversations','Events & music','Books & art'],languages:['English','Hindi'],color:'lavender'}];
const activities=[['coffee','Coffee & conversations','A little caffeine. A real connection.'],['food','Food & dining','Great food tastes better together.'],['film','Movies','Find your next movie buddy.'],['compass','City exploring','New streets. Shared discoveries.'],['music','Events & music','Make memories, not just plans.']];
let user=null,pricing={male_amount:29900},calDate=new Date(),selectedDate='',selectedSlot='',viewMode='month';
const root=document.getElementById('app');
const link=(path,text,cls='')=>`<a href="${path}" data-link class="${cls}">${text}</a>`;
const btn=(text,action,cls='btn btn-primary')=>`<button type="button" class="${cls}" data-action="${action}">${text}</button>`;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(!r.ok)throw new Error(data.error||'Something went wrong. Please try again.');return data;}
function header(){return `<header class="site-header"><div class="container header-inner">${link('/',`<span class="logo-mark">${icon('heart')}</span>saathlumi<span class="logo-dot">.</span>`,'brand')}<nav class="desktop-nav" aria-label="Main navigation">${link('/browse','Find a companion',location.pathname==='/browse'?'active':'')}${link('/how-it-works','How it works')}${link('/safety','Safety first')}${link('/pricing','Pricing')}</nav><div class="header-actions">${user?`${link('/dashboard',icon('user')+' My space','login-link')}${btn(icon('logout')+'<span class="sr-only">Log out</span>','logout','icon-button')}`:`${link('/login','Log in','login-link')}${link('/register','Get started '+icon('arrow'),'btn btn-primary btn-small')}`}<button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button></div></div><nav class="mobile-nav" hidden>${link('/browse','Find a companion')}${link('/how-it-works','How it works')}${link('/safety','Safety first')}${link('/pricing','Pricing')}${link('/dashboard','My space')}</nav></header>`;}
function footer(){return `<footer class="site-footer"><div class="container footer-grid"><section>${link('/',`<span class="logo-mark">${icon('heart')}</span>saathlumi<span class="logo-dot">.</span>`,'brand')}<p>Because life is better<br>with a little good company.</p><span class="footer-age">18+ only · Platonic connections</span></section><section><h3>Explore</h3>${link('/browse','Find a companion')}${link('/register?role=companion','Become a companion')}${link('/how-it-works','How it works')}${link('/pricing','Membership')}</section><section><h3>We’re here for you</h3>${link('/safety','Safety centre')}${link('/guidelines','Community guidelines')}${link('/contact','Contact & support')}${link('/#faq','FAQs')}</section><section><h3>The important things</h3>${link('/terms','Terms of service')}${link('/privacy','Privacy policy')}${link('/refunds','Cancellation & refunds')}<p class="footer-note">Built around respect.<br>Designed for real connection.</p></section></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Saathlumi. All rights reserved.</span><span>Made for meaningful moments in India <span class="coral">${icon('heart')}</span></span></div></footer>`;}
function searchBar(){return `<form id="discovery-search" class="search-panel"><label><span>${icon('pin')} YOUR CITY</span><select name="city" aria-label="Your city"><option value="">Choose your city</option>${['Bengaluru','Mumbai','Delhi','Pune','Hyderabad'].map(c=>`<option>${c}</option>`).join('')}</select></label><label><span>${icon('coffee')} WHAT’S THE PLAN?</span><select name="activity" aria-label="Activity"><option value="">Pick an activity</option>${activities.map(a=>`<option>${a[1]}</option>`).join('')}</select></label><label><span>${icon('calendar')} WHEN?</span><input type="date" name="date" min="${today()}" aria-label="Meeting date"></label><button class="btn btn-primary" type="submit">${icon('search')} Find a companion</button></form>`;}
function profileCard(p){return `<article class="profile-card"><a class="profile-image" href="/companions/${p.id}" data-link><img src="/static/images/${p.image}" alt="Illustrative portrait for fictional sample ${p.name}" loading="lazy"><span class="sample-badge">Sample profile</span><span class="photo-caption">Illustrative image · Not a real member</span></a><div class="profile-content"><div class="profile-name"><h3>${p.name}, ${p.age}</h3><span class="profile-round">${icon('arrow')}</span></div><p class="location">${icon('pin')} ${p.city} <span>· ${p.area}</span></p><p class="profile-line">${p.line}</p><div class="tags">${p.interests.slice(0,2).map(t=>`<span>${icon(activities.find(a=>a[1]===t)?.[0]||'spark')}${t}</span>`).join('')}</div>${link('/companions/'+p.id,'Meet '+p.name+' '+icon('arrow'),'profile-link')}</div></article>`;}
function howSteps(){return `<div class="steps-grid">${[['user','01','A little about you','Create your profile. Share your interests and what good company means to you.'],['search','02','Find your kind of person','Discover companions who share your interests, in your city.'],['calendar','03','Make a plan','Choose an activity and a time. Send a request and wait for a mutual yes.'],['heart','04','Meet. Connect. Enjoy.','Meet in a public place, be yourself, and make a meaningful moment.']].map(s=>`<article class="step"><div class="step-icon">${icon(s[0])}<span>${s[1]}</span></div><h3>${s[2]}</h3><p>${s[3]}</p></article>`).join('')}</div>`;}
function pricingCards(){return `<div class="pricing-grid"><article class="price-card"><span class="eyebrow">YOUR FIRST HELLO</span><h3>A new connection.<br>Starts with you.</h3><div class="price">Join<span>Create your account to get started</span></div><ul class="check-list"><li>${icon('check')} Create your own profile</li><li>${icon('check')} Discover like-minded companions</li><li>${icon('check')} View your membership details after login</li></ul>${link('/register','Create an account '+icon('arrow'),'btn btn-outline')}</article><article class="price-card featured-price"><span class="price-ribbon">ONE PAYMENT. MORE POSSIBILITIES.</span><span class="eyebrow">FOR MEN</span><h3>Good company.<br>One simple membership.</h3><div class="price">₹${pricing.male_amount/100}<span>One time. No subscriptions.</span></div><ul class="check-list"><li>${icon('check')} Your profile & companion discovery</li><li>${icon('check')} Unlock booking requests & messaging</li><li>${icon('check')} No automatic renewals. No surprises.</li></ul>${link(user?'/checkout':'/register?gender=man','Get started '+icon('arrow'),'btn btn-primary')}</article></div><p class="pricing-disclaimer">Membership is for platform access, not a meeting fee. No companion charges are configured.<br>Plans require mutual acceptance. Personal activity expenses are separate.</p>`;}
function faq(){const items=[['What is Saathlumi, exactly?','Saathlumi is an adults-only platform for finding company for platonic activities—coffee, a movie, a meal, or exploring your city. It is not a dating guarantee or a sexual-services platform.'],['Is this a dating or escort service?','No. All connections are strictly platonic. Sexual services, coercion, harassment, and trafficking are prohibited. Everyone’s boundaries and consent must be respected.'],['What does the ₹299 membership include?','The ₹299 one-time paid membership is intended to unlock booking requests and permitted messaging. Your applicable membership details are shown after login and before any payment. It is not a per-meeting charge, and payment never guarantees an accepted request. Payments are disabled in this preview.'],['How do I stay safe when meeting someone?','Meet in a busy public place, tell someone you trust about your plan, keep contact details private until comfortable, and leave whenever you wish. Report concerning behavior through the safety centre.'],['Can I cancel a plan?','Yes. Either person can withdraw consent or cancel. Let the other person know as early as possible. Cancellation rules and membership refunds are separate; review the draft Cancellation & Refund Policy.']];return `<div class="faq-list">${items.map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div>`;}
function home(){return `<main><section class="hero-section"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow hero-eyebrow"><span class="tiny-flower">${icon('spark')}</span> REAL PEOPLE. REAL CONNECTIONS.</span><h1>Good company.<br><em>Meaningful</em><br>moments.</h1><p>Life’s little moments are better when shared.<br class="desktop-br"> Find a like-minded companion for coffee, conversations,<br class="desktop-br"> and everything in between. Strictly platonic. Always genuine.</p><div class="hero-actions">${link('/browse','Find a companion '+icon('arrow'),'btn btn-primary')}${link('/register?role=companion','Become a companion','btn btn-outline')}</div><div class="hero-assurances"><span>${icon('shield')} Safety comes first</span><span>${icon('heart')} No pressure, just connection</span></div></div><div class="hero-visual"><div class="hero-image-wrap"><img class="hero-image" src="/static/images/coffee-friends.jpg" alt="Two adults enjoying a conversation over coffee" fetchpriority="high"><div class="hero-image-shade"></div><span class="hero-photo-note">A glimpse of good company · Lifestyle image</span><div class="photo-quote">Less scrolling.<br>More living<span>.</span></div></div><div class="floating-pill top-pill"><span class="pill-icon">${icon('coffee')}</span><span>A coffee. A conversation.<br><strong>A better kind of day.</strong></span></div><div class="floating-pill bottom-pill"><span class="pill-icon sage-icon">${icon('shield')}</span><span>Your comfort.<br><strong>Always the priority.</strong></span><span class="little-dot"></span></div><div class="decor-spark">${icon('spark')}</div><div class="orbit-heart">${icon('heart')}</div></div></div><div class="container search-container">${searchBar()}</div></section><div class="values-strip"><div class="container">${[['shield','Respectful by design'],['users','Adults 18+ only'],['heart','100% platonic connections'],['lock','Your privacy matters']].map(v=>`<span>${icon(v[0])}${v[1]}</span>`).join('')}</div></div><section class="section container" id="how-it-works"><div class="section-heading centered"><span class="eyebrow">A HELLO CAN CHANGE YOUR DAY</span><h2>Good company, in four simple steps.</h2><p>A little less complicated. A lot more human.</p></div>${howSteps()}</section><section class="discover-section"><div class="container"><div class="section-heading heading-row"><div><span class="eyebrow">FIND YOUR KIND OF COMPANY</span><h2>Different people. Shared interests.</h2><p>Get a feel for the connections you could make.</p></div>${link('/browse','Explore companions '+icon('arrow'),'text-link')}</div><div class="sample-notice">${icon('info')} A little preview: these are fictional sample profiles, not available members.</div><div class="profiles-grid">${profiles.map(profileCard).join('')}</div></div></section><section class="section container activities-section"><div class="section-heading centered"><span class="eyebrow">BIG MEMORIES. LITTLE PLANS.</span><h2>What are you in the mood for?</h2><p>Whatever your kind of day, there’s a way to share it.</p></div><div class="activities-grid">${activities.map(a=>link('/browse?activity='+encodeURIComponent(a[1]),`<span class="activity-icon">${icon(a[0])}</span><h3>${a[1]}</h3><p>${a[2]}</p><span class="activity-arrow">${icon('arrow')}</span>`,'activity-card')).join('')}</div><p class="city-line">A little closer to you <span>·</span> Bengaluru <span>·</span> Mumbai <span>·</span> Delhi <span>·</span> Pune <span>·</span> Hyderabad <small>Planned launch cities</small></p></section><section class="safety-section container"><div class="safety-art"><img src="/static/images/community.jpg" alt="Illustrative café gathering of adult friends" loading="lazy"><div class="safety-image-caption">Good connections start<br>with feeling comfortable.</div></div><div class="safety-copy"><span class="eyebrow">YOUR COMFORT IS NON-NEGOTIABLE</span><h2>Good company starts<br>with peace of mind.</h2><p>Real connection needs a foundation of respect. Your boundaries, your privacy, and your right to say no come first. Every time.</p><ul class="safety-list"><li>${icon('shield')} Clear community guidelines</li><li>${icon('heart')} Mutual consent, at every step</li><li>${icon('lock')} Privacy-conscious profiles & easy reporting</li></ul>${link('/safety','Explore our safety centre '+icon('arrow'),'text-link')}</div></section><section class="section container" id="pricing"><div class="section-heading centered"><span class="eyebrow">SIMPLE, JUST LIKE IT SHOULD BE</span><h2>A little investment in good company.</h2><p>Transparent membership. No subscriptions. No mixed signals.</p></div>${pricingCards()}</section><section class="faq-section container" id="faq"><div><span class="eyebrow">WONDERING ABOUT SOMETHING?</span><h2>A few good<br>questions.</h2><p>Here’s a little clarity before your first hello.</p>${link('/contact','Have another question? '+icon('arrow'),'text-link')}</div>${faq()}</section><section class="cta-section container"><span class="cta-spark">${icon('spark')}</span><div><span class="eyebrow">SOMETHING GOOD STARTS WITH A HELLO</span><h2>Your next good moment is waiting.</h2><p>Make a plan. Meet someone new. Enjoy a little good company.</p></div>${link('/register','Let’s get started '+icon('arrow'),'btn btn-primary')}<span class="cta-heart">${icon('heart')}</span></section></main>`;}
function browse(){const q=new URLSearchParams(location.search);return `<main class="container page-main"><div class="page-title"><span class="eyebrow">YOUR NEXT GOOD CONNECTION</span><h1>Find your kind of company.</h1><p>Shared interests are a lovely place to start.</p></div><form class="browse-filters" id="browse-filters"><label>Search<input name="q" placeholder="Name or interest" value="${esc(q.get('q')||'')}"></label><label>City<select name="city"><option value="">All cities</option>${['Bengaluru','Mumbai','Delhi','Pune','Hyderabad'].map(c=>`<option ${q.get('city')===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Activity<select name="activity"><option value="">Any activity</option>${activities.map(a=>`<option ${q.get('activity')===a[1]?'selected':''}>${a[1]}</option>`).join('')}</select></label><label>Companion<select name="gender"><option value="">Everyone</option><option value="woman" ${q.get('gender')==='woman'?'selected':''}>Women</option><option value="man" ${q.get('gender')==='man'?'selected':''}>Men</option></select></label><label>Language<select name="language"><option value="">Any language</option>${['English','Hindi','Kannada','Marathi'].map(l=>`<option ${q.get('language')===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Date<input type="date" name="date" min="${today()}" value="${esc(q.get('date')||'')}"></label><button class="btn btn-primary" type="submit">${icon('search')} Search</button></form><div class="browse-toolbar"><strong id="results-count"></strong><button data-action="clear-filters" class="text-link">Clear filters</button></div><div class="sample-notice">${icon('info')} Preview mode · All profiles and availability shown are fictional. Live discovery is not open yet.</div><div id="profile-results" class="profiles-grid"></div><p class="end-results">You’re all caught up. Real profiles will appear here after launch and moderation.</p></main>`;}
function filterProfiles(){const f=document.getElementById('browse-filters');if(!f)return;const v=Object.fromEntries(new FormData(f));const found=profiles.filter(p=>(!v.city||p.city===v.city)&&(!v.activity||p.interests.includes(v.activity))&&(!v.gender||p.gender===v.gender)&&(!v.language||p.languages.includes(v.language))&&(!v.q||JSON.stringify(p).toLowerCase().includes(v.q.toLowerCase())));document.getElementById('results-count').textContent=`${found.length} sample companion${found.length===1?'':'s'}${v.date?' · Example availability on '+v.date:''}`;document.getElementById('profile-results').innerHTML=found.length?found.map(profileCard).join(''):`<section class="empty-state"><span class="empty-icon">${icon('search')}</span><h2>No matches just yet.</h2><p>Try a different city or activity. Only three sample profiles are available in this preview.</p>${btn('Reset filters','clear-filters','btn btn-outline')}</section>`;}
function profilePage(p){return `<main class="container page-main"><div class="breadcrumb">${link('/browse','Discover companions')} ${icon('chevron')} ${p.name}</div><div class="sample-notice">${icon('info')} Fictional sample profile · Image is illustrative. You cannot book or message this person.</div><div class="profile-detail-grid"><article class="profile-bio"><img class="detail-photo" src="/static/images/${p.image}" alt="Illustrative sample portrait"><div class="profile-body"><span class="eyebrow">A LITTLE ABOUT YOUR SAMPLE COMPANION</span><h1>${p.name}, ${p.age}</h1><p class="location">${icon('pin')} ${p.area}, ${p.city}</p><h3>Good company looks like…</h3><p>${p.bio}</p><h3>Things we could share</h3><div class="tags">${p.interests.map(i=>`<span>${i}</span>`).join('')}</div><h3>A common language</h3><p>${p.languages.join(' · ')}</p><h3>Comfort comes first</h3><p>Public places only. Platonic activities. No pressure to share personal contact details. Either person can leave or cancel at any time.</p><div class="sample-notice">${icon('shield')} No identity or age verification has been performed for sample profiles.</div></div></article><aside class="booking-panel"><span class="eyebrow">LET’S PICTURE A PLAN</span><h2>A time to connect.</h2><p class="muted">Explore the booking experience.<br>Sample availability · Asia/Kolkata (IST)</p><div id="calendar-widget">${calendar()}</div><form id="booking-form" data-profile="${p.id}"><label>What’s the plan?<select name="activity">${p.interests.map(i=>`<option>${i}</option>`).join('')}</select></label><label>Duration<select name="duration"><option value="60">1 hour</option><option value="90">1.5 hours</option><option value="120">2 hours</option></select></label><label>A public meeting place<input name="venue" placeholder="e.g. A café in ${p.area}" required maxlength="150"></label><label>A little hello<textarea name="message" placeholder="Tell them a little about your plan…" maxlength="500" required></textarea></label><label class="checkbox-label"><input type="checkbox" required> I understand that all meetings are platonic, in public, and require mutual consent.</label><button class="btn btn-primary full" type="submit">Preview your request ${icon('arrow')}</button><p class="form-note">This is a preview. No request will be sent.</p></form></aside></div></main>`;}
function calendar(){const y=calDate.getFullYear(),m=calDate.getMonth(),days=new Date(y,m+1,0).getDate(),first=(new Date(y,m,1).getDay()+6)%7;let cells='';for(let i=0;i<first;i++)cells+='<span></span>';for(let d=1;d<=days;d++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;cells+=`<button type="button" class="day ${selectedDate===date?'selected':''} ${date===today()?'today':''}" data-date="${date}" ${date<today()?'disabled':''}>${d}</button>`;}return `<div class="calendar"><div class="calendar-heading"><strong>${calDate.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</strong><div><button type="button" class="icon-button" data-action="prev-month" aria-label="Previous month"><span class="flip">${icon('chevron')}</span></button><button type="button" class="icon-button" data-action="next-month" aria-label="Next month">${icon('chevron')}</button></div></div><div class="calendar-weekdays">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${cells}</div>${selectedDate?`<div class="slot-heading">${esc(selectedDate)} · Sample times (IST)</div><div class="time-slots">${['10:00','12:00','14:00','16:00','18:00'].map(t=>`<button type="button" data-slot="${t}" class="time-slot ${selectedSlot===t?'selected':''}" ${new Date(selectedDate+'T'+t+':00+05:30').getTime()<Date.now()+3600000?'disabled':''}>${t}</button>`).join('')}</div>`:'<p class="calendar-hint">Pick a date for sample availability</p>'}</div>`;}
function authPage(type){const isRegister=type==='register',reset=type==='reset-password',forgot=type==='forgot-password',verify=type==='verify-email';const q=new URLSearchParams(location.search);return `<main class="auth-page container"><section class="auth-story"><span class="eyebrow">A LITTLE GOOD COMPANY</span><h1>Every connection<br>starts with<br><em>a simple hello.</em></h1><p>A coffee, a new perspective, or just someone to share the day with. Find the moments that make life a little more meaningful.</p><img src="/static/images/community.jpg" alt="Illustrative scene of friends connecting in a café"><span class="story-note">Platonic. Respectful. Always your choice.</span></section><section class="auth-card"><span class="mini-brand">${icon('heart')}</span><h2>${isRegister?'Your next chapter starts here.':forgot?'Let’s get you back in.':reset?'A fresh start.':verify?'Verify your email.':'Good to see you again.'}</h2><p class="muted">${isRegister?'A few details. A world of good company.':forgot?'We’ll email you a secure password reset link.':reset?'Choose a strong, unique password.':verify?'Confirm your email using the link in your inbox.':'Log in to your little corner of Saathlumi.'}</p><div class="inline-notice">${icon('info')} Development preview — use test details and a password you don’t use elsewhere.</div><form id="auth-form" data-type="${type}">${isRegister?`<label>Your name<input name="name" autocomplete="name" required minlength="2" maxlength="60" placeholder="What should we call you?"></label>`:''}${!reset&&!verify?`<label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" maxlength="254" required></label>`:''}${!forgot&&!verify?`<label>Password<div class="password-input"><input name="password" type="password" autocomplete="${isRegister||reset?'new-password':'current-password'}" minlength="${isRegister||reset?'12':'1'}" maxlength="128" required placeholder="${isRegister||reset?'At least 12 characters':'Your password'}"><button type="button" data-action="toggle-password" aria-label="Show password">Show</button></div></label>`:''}${isRegister?`<div class="form-two"><label>I identify as<select name="gender" required><option value="">Select</option><option value="woman" ${q.get('gender')==='woman'?'selected':''}>Woman</option><option value="man" ${q.get('gender')==='man'?'selected':''}>Man</option><option value="self-described">Self-described</option><option value="prefer-not-to-say">Prefer not to say</option></select></label><label>Date of birth<input name="dob" type="date" required max="${new Date(new Date().setFullYear(new Date().getFullYear()-18)).toISOString().slice(0,10)}"></label></div><label class="checkbox-label"><input name="companion" type="checkbox" ${q.get('role')==='companion'?'checked':''}> I’d also like to become a companion.</label><label class="checkbox-label"><input name="consent" type="checkbox" required> <span>I’m 18 or older and agree to the ${link('/terms','Terms')}, ${link('/privacy','Privacy Policy')}, and ${link('/guidelines','Community Guidelines')}.</span></label><div class="inline-notice">${icon('info')} Self-reported age is not identity verification. Adult verification is required before real meetings.</div>`:''}${type==='login'?`<div class="form-end">${link('/forgot-password','Forgot password?','text-link')}</div>`:''}<div id="form-feedback" aria-live="polite"></div><button class="btn btn-primary full" type="submit">${isRegister?'Create my account':forgot?'Send reset link':reset?'Update password':verify?'Verify email':'Log in'} ${icon('arrow')}</button>${verify?`<input type="hidden" name="token" value="${esc(q.get('token')||'')}">`:''}</form><p class="auth-switch">${isRegister?`Already a member? ${link('/login','Log in')}`:`New around here? ${link('/register','Create an account')}`}</p><p class="form-note">${icon('lock')} Your information stays private.<br>Email delivery requires provider configuration in this preview.</p></section></main>`;}
function dashboard(){if(!user)return gate('Your space for good company.','Log in to see your profile, membership, and plans.');return `<main class="container page-main"><div class="dashboard-heading"><div><span class="eyebrow">YOUR LITTLE CORNER OF TOGETHERLY</span><h1>Hello, ${esc(user.name)}.</h1><p>Here’s to your next meaningful moment.</p></div>${link('/browse','Find a companion '+icon('arrow'),'btn btn-primary')}</div><nav class="dashboard-tabs">${link('/dashboard','Overview','active')}${link('/calendar','My calendar')}${link('/messages','Messages')}${link('/onboarding','My profile')}${link('/checkout','Membership')}</nav><div class="dashboard-stats"><article>${icon('calendar')}<strong id="booking-count">0</strong><span>Upcoming plans</span></article><article>${icon('heart')}<strong>${user.membership==='active'?'Active':'Not active'}</strong><span>Membership</span></article><article>${icon('shield')}<strong>${user.email_verified?'Email confirmed':'Email pending'}</strong><span>Adult verification not completed</span></article></div>${!user.email_verified?`<div class="sample-notice">${icon('mail')} Please verify your email before booking. Email delivery is ${user.email_delivery?'configured':'not configured yet'}. ${btn('Resend email','resend-email','text-link')}</div>`:''}<div class="dashboard-grid"><section class="panel"><h2>Your upcoming plans</h2><div id="dashboard-bookings"><div class="empty-state">${icon('calendar')}<h3>A little room for something good.</h3><p>No confirmed plans yet. Explore the preview to find your kind of company.</p>${link('/browse','Explore companions '+icon('arrow'),'text-link')}</div></div></section><aside class="panel peach-panel"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h2>A profile that feels like you.</h2><p>Share a little about your interests, preferred activities, and boundaries.</p>${link('/onboarding','Complete my profile '+icon('arrow'),'btn btn-outline')}<hr><p>${icon('shield')} Real discovery opens after profile moderation and adult verification are operational.</p></aside></div><section class="panel account-actions"><h3>Your data, your choice</h3>${btn('Export my data','export-data','btn btn-outline')}${btn('Request account deletion','delete-account','text-link')}</section></main>`;}
function gate(title,text){return `<main class="container page-main"><section class="empty-state gate"><span class="empty-icon">${icon('lock')}</span><h1>${title}</h1><p>${text}</p><div class="hero-actions">${link('/login','Log in '+icon('arrow'),'btn btn-primary')}${link('/register','Create an account','btn btn-outline')}</div></section></main>`;}
function onboarding(){if(!user)return gate('Make yourself at home.','Create an account to set up your profile.');return `<main class="container page-main narrow-page"><span class="eyebrow">YOUR PROFILE, YOUR PERSONALITY</span><h1>A little more about you.</h1><p>Public profiles remain hidden until adult verification and moderation are complete.</p><form id="profile-form" class="panel"><label>Display name<input name="display_name" value="${esc(user.name)}" required maxlength="60"></label><label>City<select name="city">${['Bengaluru','Mumbai','Delhi','Pune','Hyderabad'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Approximate area<input name="area" maxlength="80" placeholder="Neighbourhood only, not your address"></label><label>Your story<textarea name="bio" maxlength="1000" placeholder="What makes a good day for you?"></textarea></label><label>Languages<input name="languages" placeholder="English, Hindi" maxlength="150"></label><label>Interests<input name="interests" placeholder="Coffee, films, art" maxlength="250"></label><label>Your boundaries<textarea name="boundaries" maxlength="600" placeholder="Public places only, no personal contact details…"></textarea></label><label class="checkbox-label"><input type="checkbox" name="companion"> I want to offer platonic companionship.</label><div class="inline-notice">${icon('info')} Photo uploads and adult verification are unavailable until storage and a verification provider are configured.</div><div id="form-feedback" aria-live="polite"></div><button class="btn btn-primary">Save my profile ${icon('check')}</button></form></main>`;}
function calendarPage(){return `<main class="container page-main"><div class="page-title"><span class="eyebrow">MAKE ROOM FOR GOOD COMPANY</span><h1>Your calendar.</h1><p>One good plan at a time. All times shown in Asia/Kolkata (IST).</p></div><div class="sample-notice">${icon('info')} Calendar explorer · This shows sample slots, not saved companion availability. Availability publishing is not yet enabled.</div><div class="calendar-page-grid"><section class="panel"><div class="view-switch">${['month','week','day'].map(v=>`<button data-view="${v}" class="${viewMode===v?'active':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><div id="calendar-widget">${calendar()}</div></section><section class="panel"><span class="eyebrow">A DAY WITH POSSIBILITIES</span><h2 id="calendar-selection">${selectedDate||'Choose your day.'}</h2><div id="agenda-detail" class="empty-state">${icon('calendar')}<h3>No confirmed bookings.</h3><p>Select a day to explore sample meeting times. Your real plans will appear here once bookings open.</p>${link('/browse','Find a companion '+icon('arrow'),'text-link')}</div></section></div></main>`;}
function checkout(){return `<main class="container page-main narrow-page"><span class="eyebrow">ONE SIMPLE MEMBERSHIP</span><h1>More moments.<br>No subscriptions.</h1><section class="panel checkout-card"><h2>Saathlumi membership</h2><p>Unlock booking requests and permitted messaging.</p><div class="checkout-line"><span>One-time platform access</span><strong>${user?.gender==='woman'?'Free':'₹'+pricing.male_amount/100}</strong></div><div class="checkout-line"><span>Tax treatment</span><span>Awaiting business configuration</span></div><div class="checkout-line total"><span>${user?.gender==='woman'?'Membership':'Proposed total'}</span><strong>${user?.gender==='woman'?'Free':'₹'+pricing.male_amount/100}</strong></div><div class="inline-notice">${icon('lock')} Payments are disabled. Merchant approval, live credentials, tax configuration, and legal review are required before checkout opens.</div><button class="btn btn-primary full" disabled>Checkout not available yet ${icon('lock')}</button><p class="form-note">No payment has been taken. No automatic renewals.<br>Payment never guarantees an accepted booking.</p>${link('/refunds','Read the draft refund policy','text-link')}</section>${!user?link('/register','Create a free account first '+icon('arrow'),'text-link'):''}</main>`;}
const policies={terms:{title:'Terms of service',intro:'The foundation for respectful connections.',sections:[['Who can join','Saathlumi is intended only for adults aged 18 or older. All activities must be lawful, consensual, and strictly platonic. Self-declared age does not constitute verification.'],['Your membership','Membership eligibility and applicable charges are shown in your account before any payment. The proposed paid membership is ₹299 one time. Pricing policies require owner and legal review before launch. Membership is not a booking guarantee or payment for affection.'],['Bookings and boundaries','Every request requires the companion’s acceptance. Either person can withdraw consent. Meet in public and agree your plans clearly. No companion payouts or separate meeting fees are configured.'],['Preview limitations','The current site contains fictional profiles and sample calendars. Live booking, identity verification, payment collection, and staffed moderation are not operational.'],['Owner details','Legal entity, registered address, governing law, grievance officer, and support contact must be supplied and reviewed before public launch.']]},privacy:{title:'Your privacy matters.',intro:'A clearer picture of how your information is handled.',sections:[['Information collected','Account information includes email, name, declared date of birth, gender, password hash, policy consent, profile information, and session records. Profile and account data are stored in Cloudflare D1 in this preview environment.'],['What is kept private','Passwords are hashed. Sessions use HttpOnly cookies. Private contact details and full date of birth are not published in discovery. Sample profiles are fictional and use illustrative licensed imagery.'],['Service providers','Cloudflare supports hosting and storage. Email and payment providers require owner configuration. Razorpay would process payment information; Saathlumi must not store raw card details.'],['Your choices','You can export your account information or request deletion from your dashboard. Deletion requests require operational follow-up. Retention periods and financial record exceptions must be finalized before launch.'],['External assets','Fonts are requested from Google Fonts. Images are hosted locally. Configure final provider disclosures, lawful purposes, retention schedules, and grievance contacts before launch.']]},refunds:{title:'Plans change. That’s okay.',intro:'Cancellation and refund policy — draft for review.',sections:[['Meeting cancellations','Either person may cancel or withdraw consent at any time. Communicate as early as possible. This preview does not charge meeting cancellation fees.'],['Membership versus meetings','The proposed ₹299 is a one-time platform fee, not a meeting fee. A declined or cancelled meeting is not automatically the same as cancelling platform membership.'],['Payments are not live','No payments can be collected in this preview. Refund eligibility, processing periods, complaint contacts, and mandatory consumer rights must be settled before payments are enabled.'],['Refunded or disputed memberships','The planned integration revokes paid access after a full refund or an adverse payment dispute. Genuine disputes require manual review and a published appeals procedure.']]},guidelines:{title:'Good company. Shared values.',intro:'A community built on mutual respect.',sections:[['Adults only. No exceptions.','Participation by anyone under 18 is prohibited. Report any account you believe may belong to a minor.'],['Keep it platonic','No sexual services, trafficking, coercion, threats, or exploitation. Payment never entitles anyone to affection, physical contact, or continued participation.'],['Respect every no','Consent can be withdrawn at any moment. No repeated unwanted contact. Respect blocks, boundaries, privacy choices, and personal space.'],['Be honest and thoughtful','Use accurate profile information. Do not impersonate others, solicit money, share private information without permission, or publish misleading reviews.'],['Speak up safely','Use reporting and blocking controls when live member interactions are enabled. Moderation escalation and appeal procedures must be staffed before launch.']]}};
function policyPage(kind){const p=policies[kind];return `<main class="container page-main narrow-page"><span class="eyebrow">THE IMPORTANT THINGS</span><h1>${p.title}</h1><p class="lead">${p.intro}</p><div class="sample-notice">${icon('info')} Draft policy · Requires professional review and business details before launch.</div><article class="policy-body">${p.sections.map(([h,t])=>`<section><h2>${h}</h2><p>${t}</p></section>`).join('')}</article></main>`;}
function safety(){return `<main class="container page-main"><section class="safety-hero"><span class="shield-large">${icon('shield')}</span><span class="eyebrow">YOUR COMFORT COMES FIRST</span><h1>Real connection.<br>Real boundaries.</h1><p>You should never have to choose between meeting someone new and feeling comfortable. Your choices are always yours.</p></section><div class="safety-cards">${[['pin','Public place. Peace of mind.','Choose a busy café, gallery, or other public venue. Arrange your own transport and avoid sharing your home address.'],['users','Keep someone in the loop.','Tell a trusted person where you are going and when you expect to return. Check in with them after your meeting.'],['heart','A yes is never an obligation.','You can change your mind, cancel a plan, or leave. Membership never creates a right to another person’s time or attention.'],['lock','A little privacy goes a long way.','Keep conversations on the platform when available. Never send money or sensitive documents to another member.'],['shield','Notice something? Speak up.','Blocking and reporting must be available for real member interactions. Live moderation is not active in this preview.'],['message','Not an emergency service.','Saathlumi does not provide emergency monitoring. In immediate danger in India, contact emergency services on 112.']].map(v=>`<article class="panel">${icon(v[0])}<h2>${v[1]}</h2><p>${v[2]}</p></article>`).join('')}</div><div class="centered">${link('/guidelines','Read our community guidelines '+icon('arrow'),'btn btn-primary')}</div></main>`;}
function messages(){if(!user)return gate('A hello goes a long way.','Log in to see your conversations.');return `<main class="container page-main"><span class="eyebrow">A SPACE FOR CONVERSATION</span><h1>Your messages.</h1><section class="panel empty-state">${icon('message')}<h2>No conversations just yet.</h2><p>Conversations open after mutual booking acceptance, with active membership and verification.<br>Sample profiles cannot receive messages.</p>${link('/browse','Explore companions '+icon('arrow'),'btn btn-primary')}</section></main>`;}
function contact(){return `<main class="container page-main narrow-page"><span class="eyebrow">LET’S CLEAR THINGS UP</span><h1>A question?<br>We’re listening.</h1><p>Start with our FAQs and community guidelines.</p><div class="panel"><h2>Support is being set up.</h2><p>This preview does not have a staffed support inbox. A verified business email, response times, and grievance contact will be published before launch.</p><div class="inline-notice">${icon('info')} No message submission is available yet. Do not send sensitive information.</div>${link('/#faq','Browse common questions '+icon('arrow'),'btn btn-outline')}</div><div class="panel"><h2>Need urgent help?</h2><p>We are not an emergency service. If you’re in immediate danger in India, call <a href="tel:112">112</a>.</p></div></main>`;}
function howPage(){return `<main class="container page-main"><div class="page-title centered"><span class="eyebrow">LESS COMPLICATED. MORE HUMAN.</span><h1>A little hello.<br>A whole lot of possibility.</h1><p>Good company in four simple steps.</p></div>${howSteps()}<div class="panel how-bottom"><h2>Every good plan starts with mutual consent.</h2><p>Membership lets you request a meeting, not demand one. Choose public places, respect boundaries, and remember you can always change your mind.</p>${link('/browse','Explore the preview '+icon('arrow'),'btn btn-primary')}</div></main>`;}
function render(){const path=location.pathname;let body='';if(path==='/')body=home();else if(path==='/browse')body=browse();else if(path.startsWith('/companions/')){const p=profiles.find(p=>p.id===path.split('/')[2]);body=p?profilePage(p):notFound();}else if(['/register','/login','/forgot-password','/reset-password','/verify-email'].includes(path))body=authPage(path.slice(1));else if(path==='/pricing')body=`<main class="container page-main"><div class="page-title centered"><span class="eyebrow">GOOD COMPANY, CLEAR PRICING</span><h1>Simple membership.<br>No mixed signals.</h1><p>Free account creation for everyone. No recurring payments.</p></div>${pricingCards()}<div class="sample-notice pricing-review">${icon('info')} Before launch: gender-based pricing requires legal and provider review. Pricing for self-described and undisclosed genders is awaiting an owner decision. Taxes are not configured; checkout is disabled.</div></main>`;else if(path==='/dashboard')body=dashboard();else if(path==='/onboarding')body=onboarding();else if(path==='/calendar'||path==='/availability')body=calendarPage();else if(path==='/checkout'||path==='/payment-result')body=checkout();else if(path==='/messages')body=messages();else if(path==='/safety')body=safety();else if(path==='/contact')body=contact();else if(path==='/how-it-works')body=howPage();else if(policies[path.slice(1)])body=policyPage(path.slice(1));else if(path==='/admin')body=gate('Administration is protected.','Administrative access is disabled until MFA and administrator provisioning are configured.');else body=notFound();root.innerHTML=header()+body+footer();document.title=(path==='/'?'Good company. Meaningful moments.':path.split('/')[1].replaceAll('-',' ').replace(/^./,s=>s.toUpperCase()))+' | Saathlumi';if(path==='/browse')filterProfiles();if(path==='/onboarding'&&user)loadProfile();if(path==='/dashboard'&&user)loadBookings();if(location.hash)setTimeout(()=>document.querySelector(location.hash)?.scrollIntoView({behavior:'smooth'}),80);}
function notFound(){return `<main class="container page-main empty-state"><span class="eyebrow">404 · A LITTLE OFF THE PATH</span><h1>This isn’t the moment<br>you were looking for.</h1><p>Let’s get you back to some good company.</p>${link('/','Back home '+icon('arrow'),'btn btn-primary')}</main>`;}
function navigate(path){history.pushState({},'',path);selectedDate='';selectedSlot='';render();window.scrollTo(0,0);}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function modal(title,content){const d=document.getElementById('app-dialog');d.innerHTML=`<button class="dialog-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button><span class="mini-brand">${icon('calendar')}</span><h2>${title}</h2>${content}`;d.showModal();}
function feedback(text,error=false){const el=document.getElementById('form-feedback');if(el){el.className=error?'form-error':'form-success';el.textContent=text;}}
function refreshCalendar(){const el=document.getElementById('calendar-widget');if(el)el.innerHTML=calendar();const label=document.getElementById('calendar-selection');if(label)label.textContent=selectedDate||'Choose your day.';applyCalendarView();}
function applyCalendarView(){const days=document.querySelector('.calendar-days');if(!days||location.pathname!='/calendar'&&location.pathname!='/availability')return;if(viewMode!=='month'){const current=selectedDate||today();const day=new Date(current+'T12:00:00'),weekday=(day.getDay()+6)%7;const start=new Date(day);start.setDate(day.getDate()-weekday);const end=new Date(start);end.setDate(start.getDate()+6);days.querySelectorAll('[data-date]').forEach(b=>{const d=new Date(b.dataset.date+'T12:00:00');b.hidden=viewMode==='day'?b.dataset.date!==current:d<start||d>end;});days.querySelectorAll('span').forEach(s=>s.hidden=true);} }
document.addEventListener('click',async e=>{const a=e.target.closest('a[data-link]');if(a){if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigate(a.getAttribute('href'));return;}const d=e.target.closest('[data-date]');if(d){selectedDate=d.dataset.date;selectedSlot='';refreshCalendar();return;}const s=e.target.closest('[data-slot]');if(s){selectedSlot=s.dataset.slot;refreshCalendar();return;}const v=e.target.closest('[data-view]');if(v){viewMode=v.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===v));refreshCalendar();return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='menu'){const n=document.querySelector('.mobile-nav');n.hidden=!n.hidden;}if(action==='clear-filters'){document.querySelectorAll('#browse-filters input,#browse-filters select').forEach(el=>el.value='');history.replaceState({},'','/browse');filterProfiles();}if(action==='toggle-password'){const input=b.previousElementSibling;input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Show':'Hide';}if(action==='prev-month'||action==='next-month'){calDate=new Date(calDate.getFullYear(),calDate.getMonth()+(action==='next-month'?1:-1),1);refreshCalendar();}if(action==='close-modal')document.getElementById('app-dialog').close();if(action==='logout'){try{await api('/api/auth/logout',{method:'POST'});user=null;navigate('/');toast('You’ve been logged out. See you soon.');}catch(err){toast(err.message);}}if(action==='resend-email'){try{const r=await api('/api/auth/resend',{method:'POST'});toast(r.message);}catch(err){toast(err.message);}}if(action==='export-data'){try{const data=await api('/api/account/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='saathlumi-my-data.json';a.click();URL.revokeObjectURL(url);}catch(err){toast(err.message);}}if(action==='delete-account'){modal('Your data, your choice.',`<p>Submit an account deletion request? Your profile will be hidden immediately. Actual deletion and any financial retention exceptions require an operator’s review; no processing deadline is promised in this preview.</p>${btn('Submit deletion request','confirm-delete','btn btn-primary')}`);}if(action==='confirm-delete'){try{await api('/api/account/deletion',{method:'POST'});document.getElementById('app-dialog').close();toast('Deletion request recorded. Your profile is hidden pending review.');}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const v=Object.fromEntries(new FormData(f));if(f.id==='discovery-search'){navigate('/browse?'+new URLSearchParams(v));return;}if(f.id==='browse-filters'){history.replaceState({},'','/browse?'+new URLSearchParams(v));filterProfiles();return;}if(f.id==='booking-form'){if(!selectedDate||!selectedSlot){toast('Choose a date and an available time first.');return;}const p=profiles.find(p=>p.id===f.dataset.profile);modal('A little preview of your plan.',`<div class="sample-notice">${icon('info')} Not a real booking · No request has been sent.</div><dl class="booking-summary"><dt>Sample companion</dt><dd>${p.name}</dd><dt>Your plan</dt><dd>${esc(v.activity)}</dd><dt>Date & time</dt><dd>${selectedDate} at ${selectedSlot} IST</dd><dt>Duration</dt><dd>${esc(v.duration)} minutes</dd><dt>Public venue</dt><dd>${esc(v.venue)}</dd></dl><p>Real requests will require an active membership, email confirmation, adult verification, and a live companion’s acceptance.</p>${link('/register','Create your account '+icon('arrow'),'btn btn-primary full')}`);return;}const submit=f.querySelector('[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{if(f.id==='auth-form'){const type=f.dataset.type;if(type==='register'){const r=await api('/api/auth/register',{method:'POST',body:JSON.stringify({...v,consent:v.consent==='on',companion:v.companion==='on'})});user=r.user;navigate('/dashboard');toast(r.message);}else if(type==='login'){const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(v)});user=r.user;navigate('/dashboard');}else if(type==='forgot-password'){const r=await api('/api/auth/forgot',{method:'POST',body:JSON.stringify(v)});feedback(r.message);}else if(type==='reset-password'){await api('/api/auth/reset',{method:'POST',body:JSON.stringify({...v,token:new URLSearchParams(location.search).get('token')})});navigate('/login');toast('Password updated. Please log in again.');}else if(type==='verify-email'){await api('/api/auth/verify',{method:'POST',body:JSON.stringify(v)});const me=await api('/api/auth/me');user=me.user;navigate('/dashboard');toast('Email confirmed. Thank you!');}}if(f.id==='profile-form'){await api('/api/profile',{method:'PUT',body:JSON.stringify({...v,companion:v.companion==='on'})});feedback('Profile saved. It stays private until verification and moderation are complete.');}}catch(err){feedback(err.message,true);}finally{if(submit)submit.disabled=false;}});
async function loadProfile(){try{const data=await api('/api/profile');if(!data.profile)return;const f=document.getElementById('profile-form');if(!f)return;for(const [k,v]of Object.entries(data.profile)){const input=f.elements.namedItem(k);if(input&&input.type!=='checkbox')input.value=v||'';}f.elements.companion.checked=!!data.profile.companion;}catch(err){toast(err.message);}}
async function loadBookings(){try{const {bookings}=await api('/api/bookings');const count=document.getElementById('booking-count');if(count)count.textContent=bookings.filter(b=>b.status==='accepted').length;}catch(err){toast(err.message);}}
window.addEventListener('popstate',render);document.getElementById('app-dialog').addEventListener('click',e=>{if(e.target.tagName==='DIALOG')e.target.close();});document.addEventListener('click',e=>{if(e.target.closest('#app-dialog a[data-link]'))document.getElementById('app-dialog').close();});
render();Promise.all([api('/api/auth/me').then(d=>user=d.user),api('/api/config').then(d=>pricing=d.pricing)]).then(()=>{if(!document.querySelector('input:focus,textarea:focus,select:focus'))render();}).catch(()=>{});
